export function roofLinePitchFactor(pitchRiseOver12: number): number {
  return Math.sqrt(pitchRiseOver12 ** 2 + 12 ** 2) / 12;
}

export function roofLineAdjustedFeet(line: RoofLineMeasurement): number {
  const meta = roofLineTypeMeta(line.type);
  if (meta.pitchAdjustment === "none" || line.pitchRiseOver12 === undefined) {
    return line.feet;
  }
  return line.feet * roofLinePitchFactor(line.pitchRiseOver12);
}

/** Length that counts in totals. Required-pitch lines contribute 0 until pitched. */
export function roofLineTotalFeet(line: RoofLineMeasurement): number {
  if (!roofLineIsPitchComplete(line)) return 0;
  return roofLineAdjustedFeet(line);
}

export function roofLineUsesPitch(type: RoofLineMeasurementType): boolean {
  return roofLineTypeMeta(type).pitchAdjustment !== "none";
}

export function roofLineRequiresPitch(type: RoofLineMeasurementType): boolean {
  return roofLineTypeMeta(type).pitchAdjustment === "required";
}

export function roofLineIsPitchComplete(line: RoofLineMeasurement): boolean {
  if (!roofLineRequiresPitch(line.type)) return true;
  return line.pitchRiseOver12 !== undefined;
}

