import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { RoofLineMeasurement, RoofLineMeasurementType } from "./roofLineMeasurements";
import {
  roofLineAdjustedFeet,
  roofLineIsPitchComplete,
  roofLineMeasurementTotals,
  roofLinePitchFactor,
  roofLineRequiresPitch,
  roofLineTotalFeet,
  roofLineUsesPitch,
} from "./roofLineMeasurements";

function line(
  type: RoofLineMeasurementType,
  feet: number,
  pitchRiseOver12?: number,
): RoofLineMeasurement {
  return {
    id: `${type}-${feet}-${pitchRiseOver12 ?? "plan"}`,
    type,
    start: { x: 0, y: 0 },
    end: { x: 10, y: 0 },
    feet,
    ...(pitchRiseOver12 === undefined ? {} : { pitchRiseOver12 }),
  };
}

describe("roof line pitch completeness", () => {
  it("requires pitch only for rakes", () => {
    assert.equal(roofLineRequiresPitch("rake"), true);
    assert.equal(roofLineRequiresPitch("hip"), false);
    assert.equal(roofLineRequiresPitch("valley"), false);
    assert.equal(roofLineRequiresPitch("ridge"), false);
    assert.equal(roofLineRequiresPitch("eave"), false);
  });

  it("treats hip and valley as complete without a pitch", () => {
    assert.equal(roofLineIsPitchComplete(line("hip", 10)), true);
    assert.equal(roofLineIsPitchComplete(line("valley", 10)), true);
  });

  it("treats an unpitched rake as incomplete", () => {
    assert.equal(roofLineIsPitchComplete(line("rake", 12)), false);
    assert.equal(roofLineIsPitchComplete(line("rake", 12, 6)), true);
  });
});

describe("roof line totals", () => {
  it("keeps an unpitched rake out of totals while still exposing plan length", () => {
    const rake = line("rake", 12);
    assert.equal(roofLineAdjustedFeet(rake), 12);
    assert.equal(roofLineTotalFeet(rake), 0);
    assert.equal(roofLineMeasurementTotals([rake]).rake, 0);
  });

  it("counts a pitched rake at the pitch-adjusted length", () => {
    const rake = line("rake", 12, 6);
    const expected = 12 * roofLinePitchFactor(6);
    assert.equal(roofLineTotalFeet(rake), expected);
    assert.equal(roofLineMeasurementTotals([rake]).rake, expected);
  });

  it("still counts unpitched hip and valley at plan feet", () => {
    const hip = line("hip", 8);
    const valley = line("valley", 5);
    const totals = roofLineMeasurementTotals([hip, valley]);
    assert.equal(totals.hip, 8);
    assert.equal(totals.valley, 5);
  });

  it("sums only complete rakes when mixed with plan-only rakes", () => {
    const totals = roofLineMeasurementTotals([
      line("rake", 10),
      line("rake", 12, 6),
      line("eave", 20),
    ]);
    assert.equal(totals.rake, 12 * roofLinePitchFactor(6));
    assert.equal(totals.eave, 20);
  });

  it("does not change ridge totals used by the probe report", () => {
    const ridge = line("ridge", 14);
    assert.equal(roofLineUsesPitch("ridge"), false);
    assert.equal(roofLineMeasurementTotals([ridge, line("rake", 9)]).ridge, 14);
  });
});
